import logging
import six
from abc import ABCMeta, abstractmethod

from .robot_utils import get_robot_variable
from ute_common_abstract_core.exceptions import MultipleConfigurationsDefined

logger = logging.getLogger('al.config')


@six.add_metaclass(ABCMeta)
class ConfigurationSource:
    """Abstract base class for configuration sources."""

    @abstractmethod
    def pull(self):
        """Return UE configuration."""
        pass


class BackwardCompatibleSource(ConfigurationSource):
    """Source that supports both new and legacy usage of robot variables."""
    def pull(self):
        """Return UE configuration."""
        config_from_new_variable = ConfigFromRobotVariable().pull()
        config_from_legacy_variable = ConfigFromLegacyRobotVariable().pull()
        iphy_config = ConfigFromUteTlWithIphy().pull()

        if config_from_new_variable and config_from_legacy_variable:
            err_msg = ("Detected both 'ABSTRACT_LIB_CONFIG' and "
                       "legacy 'TA/UTE_UE_CONFIG' robot variables. "
                       "Please define only one.")
            raise MultipleConfigurationsDefined(err_msg)

        if config_from_new_variable is not None:
            return config_from_new_variable

        if config_from_legacy_variable is not None:
            return config_from_legacy_variable

        return iphy_config


class ConfigFromRobotVariable(ConfigurationSource):
    """Takes configuration from ABSTRACT_LIB_CONFIG robot variable."""
    def pull(self):
        """Return UE configuration."""
        return get_config_from_robot_variable('ABSTRACT_LIB_CONFIG')


class ConfigFromLegacyRobotVariable(ConfigurationSource):
    """
    Backward compatibility source.

    Supports UTE_UE_CONFIG and TA_UE_CONFIG robot variables. If the first one
    exists, the second one is skipped.
    """
    def pull(self):
        """Return UE configuration."""
        for robot_variable_name in ('UTE_UE_CONFIG', 'TA_UE_CONFIG'):
            config = get_config_from_robot_variable(robot_variable_name)
            if config is not None:
                return config


class ConfigFromUteTlWithIphy(ConfigurationSource):
    """Takes ute configuration from 'tl' robot variable and detects if it uses Iphy."""
    def pull(self):
        """Return UE configuration."""
        config = None
        tl = get_config_from_robot_variable('tl')
        if tl is not None:
            if hasattr(tl, 'iphy') and tl.iphy:
                config = {'UE_POOLS': {'IphyUePoolDynamic': {}}}
        return config


def get_config_from_robot_variable(variable_name):
    """
    Return value of robot's variable, log a message if its not None.

    Helper function that adds config-specific logging to get_robot_variable.
    """
    config = get_robot_variable(variable_name)
    if config is not None:
        log_msg = "Config pulled from '{}{}{}' robot variable".format('${', variable_name, '}')
        logger.debug(log_msg)
    return config
